    #include "nexus/middleware/RequestTracingMiddleware.h"
    #include "nexus/util/Logger.h"
    #include <chrono>
    #include <random>
    #include <sstream>

    // ... implementation of process() and generateTraceId() ...
    void RequestTracingMiddleware::process(core::Request& req, core::Response& res, std::function<void()> next) {
        auto traceId = generateTraceId();
        req.setAttribute("traceId", traceId);
        util::Logger::info("Request Start [" + traceId + "]: " + req.getMethod() + " " + req.getUri());

        auto start = std::chrono::high_resolution_clock::now();
        next();
        auto end = std::chrono::high_resolution_clock::now();

        std::chrono::duration<double, std::milli> duration = end - start;
        res.setHeader("X-Trace-ID", traceId);
        util::Logger::info("Request End [" + traceId + "]: Status " + std::to_string(res.getStatus()) + " in " + std::to_string(duration.count()) + "ms");
    }
